ol.breadcrumb li.breadcrumb::before {
    content: none;
}

ol.breadcrumb li.breadcrumb-item::after,
ol.breadcrumb li.breadcrumb::after {
    content: "/\00a0";
    color: #FFFFFF;
}

ol.breadcrumb li.breadcrumb-item.active::after,
ol.breadcrumb li.breadcrumb-last::after {
    content: none;
}

.breadcrumb-item a,
li.breadcrumb a {
