.datepciker-drop {
    min-width: 273px;
    position: relative;
}

.datepciker-drop .arrow {
    position: absolute;
    right: 15px;
    top: 20px;
    width: 12px;
    height: 8px;
}

.datepciker-drop .arrow:after {
    -webkit-transition: -webkit-transform linear .3s;
    transition: -webkit-transform linear .3s;
    transition: transform linear .3s;
    transition: transform linear .3s, -webkit-transform linear .3s;
}

.datepciker-drop input[type="text"] {
    width: 100%;
    background: none;
    color: #2d4668;
    border-color: #ddd;
    font-size: 16px;
    line-height: 20px;
    margin: 0;
    padding: 13px 40px 14px 16px;
}

.datepciker-drop input[type="text"]::-webkit-input-placeholder {
    color: #2d4668;
}

.datepciker-drop input[type="text"]::-moz-placeholder {
    opacity: 1;
    color: #2d4668;
}

.datepciker-drop input[type="text"]:-moz-placeholder {
    color: #2d4668;
}

.datepciker-drop input[type="text"]:-ms-input-placeholder {
    color: #2d4668;
}

.datepciker-drop input[type="text"].placeholder {
    color: #2d4668;
}

.datepciker-drop input:focus~.arrow:after {
    -webkit-transform: rotate(180deg);
    -ms-transform: rotate(180deg);
    transform: rotate(180deg);
}


[class^="icon-"],
[class*=" icon-"] {
    display: inline-block;
    vertical-align: top;
    font-size: 0;
    line-height: 0;
    position: relative;
    width: 16px;
    height: 16px;
}

[class^="icon-"]:after,
[class*=" icon-"]:after {
    position: absolute;
    left: 0;
    top: 0;
    width: 100%;
    height: 100%;
    background-size: 100% 100%;
    -webkit-transition: opacity .3s linear;
    transition: opacity .3s linear;
    content: "";
}

.icon-grid:before,
.icon-list:before {
    position: absolute;
    left: 0;
    top: 0;
    width: 100%;
    height: 100%;
    background-size: 100% 100%;
    -webkit-transition: opacity .3s linear;
    transition: opacity .3s linear;
    content: "";
}

