.gradient-overlay {
    position: absolute;
    bottom: 0;
    left: 0;
    right: 0;
    height: 100%;
    background: linear-gradient(to top, rgba(0, 0, 0, 0.8), transparent);
    border-radius: inherit;
}


	.scroll-container::-webkit-scrollbar {
		width: 1rem!important;
		height: 2px;
	}
	.scroll-container::-webkit-scrollbar-track {
		box-shadow: inset 0 0 6px rgba(0, 0, 0, 0.3);
		border-radius:10px;
		height:2px;
	}
	.scroll-container::-webkit-scrollbar-thumb {
		background-color: #a6192e;
		border-radius:10px;
	}


.cls-1, .cls-2 { fill: #fff; } .cls-1 { fill-rule: evenodd; }



	#feedbackModal {

	}
	#feedbackModal .modal-title {
		margin-left:-18px;
	}
	#feedback-dialog {
		max-width: 504px !important;
		margin:auto;
	}
	.feedback-iframe {
		width:100%;
		min-height: 476px;
	}

	.btn-feedback {
		position:fixed;
		bottom: clamp(15px, calc(2vw + 10px), 20px);
		right: clamp(15px, calc(2vw + 10px), 20px);
		font-weight:bolder;
		font-size:12px;
		background: #7aace1; /*#e0e0e0 - Original*/
		color: #18222d; /* #484848 - Original */
		border:#55789d 1px solid; /*#b8b8b8 - Original*/
		padding: 6px 10px;
		opacity:1;
		border-radius: 10px 10px 0 10px;
		z-index:100;
		transition: ease-in-out 200ms;
		display:flex;
		align-items: center;
		justify-content:center;
	}
	.btn-feedback p {
		float: right;
		transition: ease-in-out 200ms;
		opacity: 1;
		transform: translateX(0);
	}
	.btn-feedback .feedback-icon {
		display:block;
	}
	.btn-feedback .feedback-icon-scrolled {
		display:none;
	}
	.btn-feedback .feedback-icon, .btn-feedback .feedback-icon-scrolled {
		width: 34px;
		margin: auto;
		padding:1px;
		fill:#18222d;
		float: left;
		transition: ease-in-out 200ms;
		flex-shrink: 0;
	}

	.btn-feedback:hover, .btn-feedback.scrolled:hover {
		background:#809ebf; /* #c2c2c2 - Original */
		color: #20272f;
		opacity: 1;
	}
	#feedbackModal .modal-body {
		padding:0!important;
	}
	@media screen and (max-width: 991px) {
		.btn-feedback, .btn-feedback::after {
			opacity:1;
		}
		.btn-feedback.scrolled svg {
		/*transform: translate(32px, 0px) !important;*/
	}
	}
	.btn-feedback.scrolled {
		width: 50px;
		height: 50px;
		padding: 0;
		border-radius: 50%;
		background:#7aace1;
		transition: ease-in-out 200ms;
	}
	.btn-feedback.scrolled .feedback-icon-scrolled {
		float:none!important;
		display:block;
		transition: ease-in-out 200ms;
		width:38px;
		margin:auto;
		position:absolute;
	}
	.btn-feedback.scrolled .feedback-icon {
		display:none;
	}
	.btn-feedback.scrolled p {
		opacity: 0;
		transform: translateX(20px); /* text slides out smoothly */
	}
